import{_ as n,C as a,o,c as i,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const c="/joinwell52/assets/figures/2026-09-01-interrupted-task-takeover.en.png",g=JSON.parse('{"title":"An Agent Was Interrupted. When Is It Safe to Take Over the Same Task?","description":"","frontmatter":{"title":"An Agent Was Interrupted. When Is It Safe to Take Over the Same Task?","date":"2026-09-01","updated":"2026-09-02","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","research_question":"When FCoP task files and their five-bucket lifecycle survive, when may a new Agent take over the same task after a Runtime interruption?","evidence_status":"Research complete; contract frozen; implementation and independent QA not claimed","publication_authorized":true,"edition":"research-center","summary":"Surviving TASK files do not grant re-execution authority. RA-7/RA-8 reached the real Dispatcher recovery method with confirmed and unknown effects, yet both returned to inbox. The study separates admission, reconciliation, and hold while preserving normal rework.","sources":"/en/research/evidence/2026-09-01-interruption-research","project_relevance":"substantive-relationship","item_id":"RIR-20260901-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-01-interrupted-task-takeover-cover.png","citation_status":"Completed","editing_status":"Completed"},"headers":[],"relativePath":"en/engineering/2026-09-01-interrupted-task-takeover.md","filePath":"en/engineering/2026-09-01-interrupted-task-takeover.md","lastUpdated":1788322453000}'),d={name:"en/engineering/2026-09-01-interrupted-task-takeover.md"};function l(p,e,h,u,f,m){const t=a("ArticleCover");return o(),i("div",null,[r(t,{image:"/assets/covers/daily-2026-09-01-interrupted-task-takeover-cover.png",kicker:"Interruption research · 01",title:"An Agent Was Interrupted. When Is Same-Task Takeover Safe?",summary:"Surviving TASK files do not grant re-execution authority. RA-7/RA-8 reached the real Dispatcher recovery method with confirmed and unknown effects, yet both returned to inbox. The study separates admission, reconciliation, and hold while preserving normal rework.",version:"RIR-20260901-01",status:"Engineering research · contract frozen",languageHref:"/zh/engineering/2026-09-01-interrupted-task-takeover",languageLabel:"中文"}),e[0]||(e[0]=s(`<h1 id="an-agent-was-interrupted-when-is-it-safe-to-take-over-the-same-task" tabindex="-1">An Agent Was Interrupted. When Is It Safe to Take Over the Same Task? <a class="header-anchor" href="#an-agent-was-interrupted-when-is-it-safe-to-take-over-the-same-task" aria-label="Permalink to &quot;An Agent Was Interrupted. When Is It Safe to Take Over the Same Task?&quot;">​</a></h1><p>An Agent disappears, but the FCoP TASK file, REPORTs, and lifecycle position remain. The obvious response is to hand the same files to another Agent and continue.</p><p>That is directionally right. Files preserve task identity and working context. They do not answer the dangerous question: <strong>how far did the interrupted Agent get before it vanished?</strong></p><p>If it never started the action, a successor may be admitted to re-execute it. If it already changed an external system and only missed its closing report, repeating the action creates a second effect. If nobody can establish the fact, automatic execution substitutes a guess for evidence. This is not a study of creating another task or redispatching work. Its subject is the <strong>same TASK</strong> in FCoP&#39;s five buckets: after an interruption, who may take it over, and on what basis should the system re-execute, reconcile, or hold it for review?</p><p>CodeFlowMu is a local multi-Agent collaboration Runtime we develop. It uses FCoP TASK and REPORT files for engineering work, while managing Sessions, leases, dispatch, approvals, and evidence. We inspected real code and tests at the V2.1.2 baseline, commit <code>919c3b48</code>. The observations belong to that baseline. As of this public revision on 2026-09-02, the subsequent contract is frozen; this article does not claim implementation, independent-QA acceptance, or release.</p><h2 id="_1-external-projects-frame-interruption-as-uncertainty" tabindex="-1">1. External projects frame interruption as uncertainty <a class="header-anchor" href="#_1-external-projects-frame-interruption-as-uncertainty" aria-label="Permalink to &quot;1. External projects frame interruption as uncertainty&quot;">​</a></h2><p><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">OpenAI Codex</a> is OpenAI&#39;s open-source coding Agent. Its <a href="https://github.com/openai/codex/pull/41916" target="_blank" rel="noreferrer">#41916</a> resumes an active thread after reconnecting, while holding possibly submitted or uncertain input for manual review instead of automatically resending it. Reconnecting does not prove that an action did not happen.</p><p><a href="https://github.com/ag2ai/ag2" target="_blank" rel="noreferrer">AG2</a> is an open-source multi-Agent framework. Its merged <a href="https://github.com/ag2ai/ag2/pull/3222" target="_blank" rel="noreferrer">#3222</a> makes durable conversation history loadable across connections and processes while explicitly not providing a cross-process lease. Readable history and safe ownership transfer are different properties.</p><p>Orkas is an open-source multi-model chat application. Its <a href="https://github.com/Orkas-AI/Orkas/pull/53" target="_blank" rel="noreferrer">#53</a> treats duplicate terminal/process events as replay and accepts finalization only once. More recovery channels also mean late writes from an old executor must be controlled.</p><p>These projects are neither dependencies nor proof of a CodeFlowMu defect. They narrow the question to a testable claim: <strong>an interruption is initially a technical fact, not business proof that the original action failed.</strong></p><h2 id="_2-task-identity-survives-an-in-memory-session-does-not" tabindex="-1">2. TASK identity survives; an in-memory Session does not <a class="header-anchor" href="#_2-task-identity-survives-an-in-memory-session-does-not" aria-label="Permalink to &quot;2. TASK identity survives; an in-memory Session does not&quot;">​</a></h2><p>Once FCoP artifacts are durable, the original TASK does not become a new task merely because an Agent process disappeared. A successor should retain the same <code>task_id</code>, path, thread lineage, and lifecycle position. It must not create a second TASK or disguise the original as a fresh dispatch.</p><p>The old Session&#39;s memory, SDK connection, and local execution handle may nevertheless be gone. The Runtime must first settle execution ownership: first check managed external work and prior ownership. Retain a live owner without creating a successor; handle an old lease only under existing reclamation conditions, then evaluate admission.</p><p>V2.1.2 already has meaningful protections. <code>reconcileLostSessions</code> retains a live managed job and its lease instead of granting another dispatch opportunity; records with no live handle converge to <code>SESSION_LOST</code>. Another probe confirmed that when a successor has taken over after restart, a late settle from the old Session cannot overwrite the reconciled record. These protections should remain.</p><p>The question is therefore not whether the old Agent can be revived. It is whether the old executor may still write, whether a successor may start, and what is known about the original effect.</p><h2 id="_3-recoverable-is-not-proof-that-no-action-occurred" tabindex="-1">3. <code>recoverable</code> is not proof that no action occurred <a class="header-anchor" href="#_3-recoverable-is-not-proof-that-no-action-occurred" aria-label="Permalink to &quot;3. \`recoverable\` is not proof that no action occurred&quot;">​</a></h2><p>The current Runtime has a technical path that labels an unsettled Session <code>recoverable</code>: for example, a Session is incomplete and no REPORT exists, so the queue may suggest recovery. That is useful for saying that the Runtime needs to handle an interruption. It does not establish whether an external action occurred.</p><p>We therefore did not assume a real payment, email, or Issue had been duplicated. A controlled probe entered the Dispatcher’s ordinary recovery method, fixed its backoff to zero, and isolated only its recovery decision:</p><table tabindex="0"><thead><tr><th>Case</th><th>Synthetic event&#39;s effect claim</th><th>Proposed safe action</th><th>Observed current state</th></tr></thead><tbody><tr><td>RA-7</td><td>effect confirmed</td><td><code>reconcile_only</code></td><td>restored to inbox</td></tr><tr><td>RA-8</td><td>effect unknown</td><td><code>hold_for_review</code></td><td>restored to the same inbox state</td></tr></tbody></table><p>Two semantically different inputs reached the same automatic pre-recovery state. The path did not consume <code>operation_fingerprint</code>, <code>operation_outcome</code>, <code>retry_policy</code>, or <code>next_safe_action</code>. This does not prove a production duplicate side effect. It proves a narrower engineering break: <strong>ordinary post-interruption recovery does not yet use effect facts as an admission input.</strong></p><p>The wording matters. Some current implementation names and queue states use <code>failed</code>, but the entry condition studied here is not <code>failed</code>. An unexpected shutdown, lost process, expired lease, or unfinished closeout is first <code>interrupted</code>. Translating it immediately into “the action failed, so re-execution is allowed” skips the fact that needs confirmation most.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>technical interruption ≠ effect absent ≠ safe to re-execute</span></span></code></pre></div><p>RA-7/RA-8 supply synthetic event claims, not facts queried from a real external system. The preserved observations, research fixture, and limits are in the <a href="/joinwell52/en/research/evidence/2026-09-01-interruption-research">evidence package</a>.</p><h2 id="_4-before-takeover-establish-whether-the-action-happened" tabindex="-1">4. Before takeover, establish whether the action happened <a class="header-anchor" href="#_4-before-takeover-establish-whether-the-action-happened" aria-label="Permalink to &quot;4. Before takeover, establish whether the action happened&quot;">​</a></h2><p>This does not add another task pool outside the five buckets. It is a controlled confirmation on the same TASK:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interruption</span></span>
<span class="line"><span>  → check live external work and prior ownership</span></span>
<span class="line"><span>  → block takeover while ownership is still valid</span></span>
<span class="line"><span>  → confirm the effect fact</span></span>
<span class="line"><span>  → re-execute / reconcile / hold for review</span></span></code></pre></div><p>There is first an admission precondition:</p><ul><li>If external work is live or prior ownership is still valid, record <code>not_admitted</code>, retain the owner, and create no successor. Valid ownership does not prove that an external action is running; the blocking reason and effect fact remain separate.</li></ul><p>Only after the original execution is no longer live can the three admission dispositions apply:</p><ul><li>If the effect is confirmed absent, a successor may <code>reexecute</code> the same TASK only with current authority, verified effect facts, and valid successor ownership.</li><li>If the effect is confirmed, do not repeat it; reconcile the REPORT, audit, or result.</li><li>If the effect is unknown, block automatic execution and use the existing FCoP fact-check and review responsibility chain.</li></ul><p>Separately, if an old owner finalizes late, reject it as a separate fencing event while retaining a diagnostic trace; it must not change the current admission disposition.</p><p><code>unknown</code> is not a failure. For a read-only operation or an executor with a stable idempotency key, confirmation may be quick. For an external operation that cannot be queried or safely deduplicated, it is the honest safe result.</p><p><img src="`+c+`" alt="An Agent Was Interrupted. When Is Same-Task Takeover Safe?"></p><p><em>Figure 1. A summary of the frozen admission contract, not an implemented V2.1.2 flow. Live work or valid prior ownership blocks takeover first; effect facts then select a disposition. Late old-owner writes are fenced separately. Source: RUN-002 and contract Rev.2; limitations are in the evidence notes.</em></p><p><a href="/joinwell52/assets/figures/2026-09-01-interrupted-task-takeover.en.png">Open full-resolution figure</a></p><h2 id="_5-reuse-existing-capabilities-within-a-frozen-narrow-contract" tabindex="-1">5. Reuse existing capabilities within a frozen, narrow contract <a class="header-anchor" href="#_5-reuse-existing-capabilities-within-a-frozen-narrow-contract" aria-label="Permalink to &quot;5. Reuse existing capabilities within a frozen, narrow contract&quot;">​</a></h2><p>CodeFlowMu need not rebuild every Agent platform. Providers can supply session recovery, execution state, and tool receipts. CodeFlowMu continues to own same-TASK leases, the FCoP lifecycle, fact checking, and final disposition.</p><p>Its existing <code>recoverTaskExecution</code> path already has governance snapshots, revision revalidation, a recovery fence, and a live-Session block. The next step is not a large “Recovery Epoch Framework.” It is the frozen narrow contract at the technical-interruption boundary. The following is a design requirement, not a baseline capability:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input = current TASK/attempt/lease identity</span></span>
<span class="line"><span>      + verified effect fact</span></span>
<span class="line"><span>      + authority valid for the current revision</span></span>
<span class="line"><span></span></span>
<span class="line"><span>disposition = reexecute | reconcile_only | hold_for_review</span></span>
<span class="line"><span></span></span>
<span class="line"><span>late old-owner finalization = stale-owner fencing event (does not supersede the disposition)</span></span></code></pre></div><p><code>hold_for_review</code> is a takeover disposition, not a sixth lifecycle bucket. It needs a defined display, block, and re-admission owner within the existing five buckets.</p><p>More importantly, this decision cannot hang from one UI button or one recovery route. Every UI, API, or background path handling a technical-interruption successor must traverse the same recovery-admission contract. Normal PM/ADMIN-authorized rework, reassignment, and new-round retry retain their existing paths without creating an interruption case. A server-side classifier distinguishes mixed-purpose entries from durable state; callers cannot label themselves exempt. <code>startSession</code> itself must not infer that re-execution is safe. Otherwise, one repaired recovery path can still be bypassed by another.</p><h2 id="_6-evidence-boundary-and-next-step" tabindex="-1">6. Evidence boundary and next step <a class="header-anchor" href="#_6-evidence-boundary-and-next-step" aria-label="Permalink to &quot;6. Evidence boundary and next step&quot;">​</a></h2><p>This study reran Session/lease, Dispatcher, governance, fact-check, EVAL, and evidence-association paths. A companion study asks how a takeover decision can remain traceable without granting diagnostics or EVAL the power to dispatch. The two studies cannot substitute for each other: one establishes effect facts; the other establishes authority and evidence continuity.</p><p>We did not simulate a physical power loss, run a browser end-to-end flow, or create a real external side effect. RA-7 and RA-8 fixed backoff to observe the recovery decision. The result cannot provide a production duplication rate or support the claim that CodeFlowMu already duplicates external actions. It supports the more useful conclusion: <strong>FCoP files keep task identity continuous after an Agent interruption; task identity continuity does not make execution authority continuous. Before another Agent can safely take over the same TASK, the Runtime must establish the prior effect fact and revalidate current execution authority.</strong></p><p>The frozen contract distinguishes two re-execution branches. Trusted no-start evidence yields <code>none_verified</code>, requiring current recovery authority and successor ownership. Repeating an identified <code>single_verified</code> operation additionally requires operation binding and available operation authority. Uninterpretable evidence and unclassified multiple operations remain on hold. IA-1–IA-12, DC-1–DC-3, and independent QA are subsequent implementation acceptance, not research results.</p><p>Companion reading: <a href="./2026-09-01-decision-evidence-continuity">Decision-evidence continuity</a> · <a href="/joinwell52/en/research/evidence/2026-09-01-interruption-research">Bilingual evidence notes</a>.</p>`,46))])}const b=n(d,[["render",l]]);export{g as __pageData,b as default};
